#[cfg(test)]
mod tests {
    use super::*;
    use OrderStatus::*;

    #[test]
    fn happy_path_flows_forward() {
        assert_eq!(next_status(Created), Some(Accepted));
        assert_eq!(next_status(Accepted), Some(PickedUp));
        assert_eq!(next_status(PickedUp), Some(Completed));
    }

    #[test]
    fn terminal_states_have_no_next() {
        assert_eq!(next_status(Completed), None);
        assert_eq!(next_status(Cancelled), None);
    }

    #[test]
    fn full_chain_reaches_completed() {
        let mut status = Created;
        let mut steps = 0;
        while let Some(next) = next_status(status) {
            status = next;
            steps += 1;
        }
        assert_eq!(status, Completed);
        assert_eq!(steps, 3);
    }

    #[test]
    fn only_early_states_are_cancellable() {
        assert!(can_cancel(Created));
        assert!(can_cancel(Accepted));
        assert!(!can_cancel(PickedUp));
        assert!(!can_cancel(Completed));
        assert!(!can_cancel(Cancelled));
    }

    #[test]
    fn status_is_copy_and_comparable() {
        let status = Accepted;
