use std::num::ParseIntError;

/// 库里的错误类型：调用方要能 match 出具体分支
// TODO: 用 thiserror 给这个枚举加上 Display（#[error(...)]）与 From（#[from]）
#[derive(Debug)]
pub enum ConfigError {
    Missing(&'static str),
    BadPort(ParseIntError),
}

fn lookup(entries: &[(&str, &str)], key: &'static str) -> Result<String, ConfigError> {
    entries
        .iter()
        .find(|(k, _)| *k == key)
        .map(|(_, v)| v.to_string())
        .ok_or(ConfigError::Missing(key))
}

fn port_of(entries: &[(&str, &str)]) -> Result<u16, ConfigError> {
    let raw = lookup(entries, "PORT")?;
    let port: u16 = raw.parse()?; // 需要 From<ParseIntError> for ConfigError
    Ok(port)
}

fn main() -> Result<(), Box<dyn std::error::Error>> {
    let entries = [("HOST", "0.0.0.0"), ("PORT", "8080")];

    let host = lookup(&entries, "HOST")?; // 需要 ConfigError: std::error::Error
    let port = port_of(&entries)?;

    println!("监听 {host}:{port}");
    Ok(())
}

