use tokio::sync::{mpsc, watch};

/// 消费任务直到收到关闭信号（或所有发送端都没了），再把队列排干，返回处理总数。
async fn run_worker(jobs: mpsc::Receiver<u32>, shutdown: watch::Receiver<bool>) -> u32 {
    let mut handled = 0;

    loop {
        tokio::select! {
            job = jobs.recv() => {
                match job {
                    Some(_) => handled += 1,
                    None => break, // 所有发送端都已 drop
                }
            }
            _ = shutdown.changed() => break, // 收到关闭信号
        }
    }

    // 优雅关闭：把已经进了队列的任务排干，不丢单
    while jobs.try_recv().is_ok() {
        handled += 1;
    }

    handled
}

#[tokio::main]
async fn main() {
    let (tx, rx) = mpsc::channel::<u32>(32);
    let (shutdown_tx, shutdown_rx) = watch::channel(false);

    let worker = tokio::spawn(run_worker(rx, shutdown_rx));

    let mut producers = Vec::new();
    for i in 0..2u32 {
        // TODO: 每个生产者任务都需要属于自己的发送端
        producers.push(tokio::spawn(async move {
            for j in 0..3u32 {
                tx.send(i * 10 + j).await.expect("worker 还活着");
            }
        }));
    }
    drop(tx); // 原始发送端必须撤掉，否则 recv() 永远等不到 None

    for producer in producers {
        producer.await.expect("生产者不应 panic");
    }

    let _ = shutdown_tx.send(true); // 接收端可能已经退出，忽略 Err
    let handled = worker.await.expect("worker 不应 panic");

    println!("worker 优雅退出，共处理 {handled} 条任务");
}
